10	    public static void sort(int[] values) {
11	        Objects.requireNonNull(values, "values");
12	
13	        if (values.length < 2) {
14	            return;
15	        }
16	
17	        for (int i = 0; i < values.length - 1; i++) {
18	            boolean swapped = false;
19	
20	            for (int j = 0; j < values.length - i - 1; j++) {
21	                if (values[j] > values[j + 1]) {
22	                    swap(values, j, j + 1);
23	                    swapped = true;
24	                }
25	            }
26	
27	            if (!swapped) {
28	                return;
29	            }
30	        }
31	    }
